// KJC-TSK-0645: kj harden points core.hooksPath at .karajan/hooks, which
// ECLIPSES the user's global hooks dir — silently disabling personal guards
// (AI-attribution commit-msg, protected-branch pre-push). Reproduced twice
// in the field. The generated hooks must chain the machine's global hook,
// guarded so machines without one are unaffected.
// HU-2762: the chain is looked up when the hook RUNS, so the generated bytes
// are the same on every machine (no more "5 modified hooks" under another HOME).
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { hookBody, PROFILE_HOOKS } from "../../src/harden/hook-templates.js";
import { installHooks, renderCanonicalHook } from "../../src/harden/harden-engine.js";

describe("hookBody chain-to-global (runtime lookup)", () => {
  it("every standard hook looks the global dir up when it runs", () => {
    for (const hook of PROFILE_HOOKS.standard) {
      const body = hookBody(hook, {}, {});
      expect(body).toContain("kj_global=$(git config --global --type=path --get core.hooksPath 2>/dev/null || true)");
      expect(body).toContain(`[ -x "$kj_global/${hook}" ]`);
      expect(body).toContain('[ "$rc" -eq 0 ] || exit "$rc"');
      expect(body).not.toContain(".git-hooks");
      expect(body).not.toContain("homedir()");
    }
  });

  it("pre-push hands the pushed refs to the chained hook", () => {
    expect(hookBody("pre-push", {}, {})).toContain(`printf '%s\\n' "$kj_push_refs" | "$kj_global/pre-push" "$@"; rc=$?`);
  });
});

describe("generation carries no machine-dependent global dir", () => {
  let dir, prevEnv;
  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), "kj-chain-"));
    execFileSync("git", ["init", "-q", "-b", "main"], { cwd: dir });
    prevEnv = process.env.GIT_CONFIG_GLOBAL;
    process.env.GIT_CONFIG_GLOBAL = path.join(dir, "empty-gitconfig");
  });
  afterEach(() => {
    if (prevEnv === undefined) delete process.env.GIT_CONFIG_GLOBAL;
    else process.env.GIT_CONFIG_GLOBAL = prevEnv;
    fs.rmSync(dir, { recursive: true, force: true });
  });

  it("installHooks().generation has no globalHooksDir key", async () => {
    const { generation } = await installHooks({ projectDir: dir });
    expect(generation).not.toHaveProperty("globalHooksDir");
  });

  it("a legacy globalHooksDir in a stored generation is ignored by the canonical render", () => {
    const gen = { profile: "standard", cmds: {}, baseBranch: "main" };
    for (const hook of PROFILE_HOOKS.standard) {
      expect(renderCanonicalHook(hook, { ...gen, globalHooksDir: "$HOME/x" })).toBe(renderCanonicalHook(hook, gen));
    }
  });
});
